public class METUpdateExciseRegisterController extends SysOperationServiceController
{
}

Method.Source:
public static void main(Args args)
{
    METUpdateExciseRegisterController controller;
   
    controller = METUpdateExciseRegisterController::construct();
    controller.startOperation();
}

/// <summary>
/// create instance of the controller class
/// </summary>
/// <returns>return METUpdateExciseRegisterController instance</returns>
public static METUpdateExciseRegisterController construct()
{
    return new METUpdateExciseRegisterController();
}

/// <summary>
/// to avoid multiple runs at the same time
/// </summary>
/// <returns>true always</returns>
public boolean mustGoBatch()
{
    return true;
}

    /// <summary>
    /// Stop creating new batch job if 1 already exists
    /// </summary>
    /// <returns>false if a job already exists</returns>
    protected boolean validate()
    {
        boolean ret;
        
        ret = super();

        if(ret)
        {
            Batch       batch;
            container   conBatchStatus = [BatchStatus::Executing, BatchStatus::Cancelling, BatchStatus::Ready,BatchStatus::Scheduled,BatchStatus::Waiting];

            select firstonly Caption,Status,RecId from batch
                    where batch.ClassNumber == classNum(METUpdateExciseRegisterController)
                    &&    batch.Status in conBatchStatus;
            
            info(batch.getsqlstatement());

            if(batch)
            {
                ret = error(strFmt('A batch with name - %1 is already setup with status - %2',batch.Caption,batch.Status));
            }
        }
    
        return ret;
    }
